import "./index.less"
import "../../style/plugins/tailwindcss.css"
import "../../style/style.css"
import "../../style/tailwind-base.css"

// V5.0 主题样式 仅在 body.jky-v5 类名下生效
import "../../style/v5/index.less"

import {COUNTRY_LANG} from "@utils/staticData"
import { cookie, groupParamsByKey, getPreviousSiblingHeadingText, initStickyHeaderNavLinkage } from '@utils/index.js'

import { countUp } from '@utils/common-global-utils';
import {RenderEmptyBlockBox} from "../../snippets/empty-block-box";
import {get, post} from '@utils/fetch.js';

function initUtils() {
    window.Jackery.Utils.get = get;
    window.Jackery.Utils.post = post;
    window.Jackery.Utils.getPreviousSiblingHeadingText = getPreviousSiblingHeadingText;
    window.Jackery.Utils.countUp = countUp;

    if (window.Shopify && window.Shopify.designMode) {
        // 编辑环境模式
        document.addEventListener('DOMContentLoaded', function () {
            document.querySelector('body').classList.add('shopify-edit-mode');
        })
    } else {
        // 仅预览或发布页模式下执行 公共空盒子版块渲染
        RenderEmptyBlockBox();
    }
}

/*
 * 判断account登录状态
*/
(function () {

    cookie.set("_jk_lang", COUNTRY_LANG.get(window.pageInfo.cr))
    cookie.set("_jk_cr", window.pageInfo.cr)

    if(groupParamsByKey()['jackery_token']) { // 保存jackerytoken
        let jackeryToken = groupParamsByKey()['jackery_token'];
        cookie.set("_jk_user", encodeURIComponent(jackeryToken));

        let _params = new URLSearchParams(window.location.search);
        _params.delete("jackery_token");
        var newUrl = window.location.origin + window.location.pathname + "?" + _params.toString();

        window.history.pushState({ path: newUrl }, "", newUrl)

        // 从 checkout 页返回，强制刷新页面
        window.addEventListener('popstate', function (event) {
            if (event.state && event.state.path) {
                const previousPage = event.state.path;
                if (previousPage.includes('checkouts')) {
                    window.location.href = newUrl
                }
            }
        })
    }

    initUtils();
})()


document.addEventListener('DOMContentLoaded', initStickyHeaderNavLinkage)

// TODO: 待迁移整理：全局函数处理
window.$(document).ready(function() {
    $('.rte table').wrap('<div class="table-wrapper"></div>');
    
    if(document.querySelector("header.site-header")) {
        const resizeObserver = new ResizeObserver((entries) => {
            const {height} = entries[0].contentRect;
            $('body').css('--jky-header-h', height + 'px')
          }
        );
        // 监听jky-header高度变化
        resizeObserver.observe(document.querySelector("header.site-header"));
    }

    // 获取 url 的 discount_code，并存储到 cookie
    // 这样跳转 checkout 页，可以自动适用折扣码
    const searchParams = window.location.search
    const decodeParams = decodeURIComponent(searchParams)
    const urlParams = new URLSearchParams(decodeParams)
    const discountCode = urlParams.get('discount_code')
    if (discountCode) {
        let d = new Date()
        d.setTime(d.getTime() + (7 * 24 * 60 * 60 * 1000)) // 7天
        document.cookie = `discount_code=${discountCode};expires=${d.toGMTString()};path=/`
    }
})
