/*
 * 全局二级导航与 Header 联动逻辑
 *
 * 作用：
 * 1. 统一管理 `.cal_scroll_target` 吸顶时与 header 的联动
 * 2. 保证 header 与二级导航在滚动过程中始终贴合、不重叠
 * 3. 兼容运行时高度变化、异步插入内容、sticky 场景与首屏带锚点进入
 */

export function initStickyHeaderNavLinkage() {
  // 二级导航吸顶与头部联动：
  // 当某个 .cal_scroll_target 到达头部区域时，头部逐步上滑离开视口，同时二级导航逐步顶到顶部（不遮挡、不重叠）
  let calScrollTargets = []
  const isEligibleTarget = (target) => {
    if (!target || !target.isConnected || !target.getClientRects().length) return false
    const style = getComputedStyle(target)
    if (style.display === 'none' || style.visibility === 'hidden') return false
    if (target.classList.contains('hidden')) return false
    if (target.classList.contains('hide-wrapper') && !target.classList.contains('show-wrapper')) return false
    return true
  }

  const refreshTargets = () => {
    // 目标可能在首屏后插入/显示，不能只在初始化抓一次；这里只保留当前可见且仍在 DOM 内的目标
    calScrollTargets = Array
      .from(document.querySelectorAll('.cal_scroll_target'))
      .filter((t) => isEligibleTarget(t))
  }

  const states = new WeakMap()
  let activeTarget = null
  let ticking = false
  // 只有在 DOM/class 变化或 resize 后才刷新目标列表，避免滚动每帧 querySelectorAll
  let targetsDirty = true
  let lastScrollY = window.scrollY || 0
  let lastImmediateUpdateTs = 0
  const TARGET_ENTER_BUFFER = 2
  const TARGET_EXIT_BUFFER = 6

  const getDocumentTop = (el) => {
    // 获取元素相对 document 的 top（使用 offsetTop 链对 sticky/fixed 场景更稳定）
    let top = 0
    let node = el
    while (node) {
      top += node.offsetTop || 0
      node = node.offsetParent
    }
    if (!top && el) {
      // 兜底：某些元素 offsetParent 链不完整时用 rect + scrollY
      top = (el.getBoundingClientRect().top || 0) + (window.scrollY || 0)
    }
    return top
  }

  const isStickyMeasureTarget = (target) => {
    if (!target) return false
    return getComputedStyle(target).position === 'sticky'
  }

  const getTargetMeasureEl = (target, state) => {
    if (state && state.measureEl && state.measureEl.isConnected) {
      return state.measureEl
    }
    const navMain = target.closest('.blocks-nav-main')
    if (navMain) return navMain
    if (isStickyMeasureTarget(target) && target.parentElement && target.parentElement !== document.body) {
      return target.parentElement
    }
    return target
  }

  const getTargetDocumentTop = (target, state) => {
    const measureEl = getTargetMeasureEl(target, state)
    if (!measureEl) return 0
    return getDocumentTop(measureEl)
  }

  const getHeaderContext = () => {
    // 头部选择优先级：
    // v5：header-v5（layout 里是 sticky top-0）
    // v4：.shopify-section.jky-header（wrapper），兜底 jky-header
    // v3：.site-header
    const headerV5El = document.querySelector('header-v5')
    const headerV4WrapperEl = document.querySelector('.shopify-section.jky-header')
    const headerV4El = document.querySelector('jky-header')
    const headerV3El = document.querySelector('.site-header')

    const el = headerV5El || headerV4WrapperEl || headerV4El || headerV3El
    if (!el) return null

    const getHeaderVarH = () => {
      // --jky-header-h：通用头部高度变量（不同头部实现会维护）
      // --header-height：v5 header-v5.js 写入的高度兜底
      const rootH = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--jky-header-h')) || 0
      const bodyH = parseFloat(getComputedStyle(document.body).getPropertyValue('--jky-header-h')) || 0
      const v5H = el === headerV5El
        ? (parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--header-height')) || 0)
        : 0
      return Math.max(rootH, bodyH, v5H)
    }

    const rectH = Math.ceil(el.getBoundingClientRect().height) || 0
    const varH = getHeaderVarH()
    const totalH = Math.max(rectH, varH)

    return {
      el,
      totalH,
      isHeaderV4: Boolean(headerV4WrapperEl || headerV4El) && (el === headerV4WrapperEl || el === headerV4El),
      isHeaderV5: Boolean(headerV5El) && el === headerV5El,
    }
  }

  const resetTarget = (target, state) => {
    // 恢复目标元素（撤销吸顶状态与联动写入的 style）
    if (!target) return
    target.classList.remove('sticky_anchor_active')
    target.classList.remove('pos_show')
    if (state && state.targetPrevTransition !== undefined) {
      target.style.transition = state.targetPrevTransition
    } else {
      target.style.transition = ''
    }
    if (state && state.targetPrevTop !== undefined) {
      target.style.top = state.targetPrevTop
    } else {
      target.style.top = ''
    }
    const navMain = state && state.navMain
    if (navMain) navMain.style.height = ''
  }

  const resetHeader = (ctx, state) => {
    // 恢复头部位置（撤销联动写入的 top）
    if (!ctx || !ctx.el) return
    ctx.el.style.transition = (state && state.headerPrevTransition) || ctx.el.style.transition || 'top 200ms ease'
    ctx.el.style.top = '0px'
  }

  const update = () => {
    // 以 rAF 节流执行，避免滚动每帧频繁读写 DOM
    ticking = false
    if (targetsDirty) {
      refreshTargets()
      targetsDirty = false
    }
    if (!calScrollTargets.length) {
      if (activeTarget) {
        const ctx = getHeaderContext()
        const prevState = states.get(activeTarget)
        resetTarget(activeTarget, prevState)
        resetHeader(ctx, prevState)
        states.delete(activeTarget)
        activeTarget = null
      }
      return
    }

    const ctx = getHeaderContext()
    if (!ctx || !ctx.totalH) return

    if (ctx.isHeaderV4 && window.innerWidth < 1024) {
      // v4 移动端菜单展开时不参与联动，避免 top 改写造成抖动
      const headerSection = document.querySelector('.shopify-section.jky-header')
      if (headerSection && headerSection.classList.contains('menu-active--open')) return
    }

    const scrolledY = window.scrollY || 0

    // 选出需要联动的目标：进入头部区域(inZone)的目标里，docTop 最靠上的那个
    let nextTarget = null
    let nextTargetTop = Infinity
    for (const t of calScrollTargets) {
      if (!isEligibleTarget(t)) {
        targetsDirty = true
        continue
      }
      const state = states.get(t)
      const docTop = getTargetDocumentTop(t, state)
      if (state) state.docTop = docTop
      const targetViewportTop = docTop - scrolledY
      const zoneThreshold = t === activeTarget
        ? (ctx.totalH + TARGET_EXIT_BUFFER)
        : (ctx.totalH - TARGET_ENTER_BUFFER)
      const inZone = targetViewportTop <= zoneThreshold
      if (inZone && docTop < nextTargetTop) {
        nextTarget = t
        nextTargetTop = docTop
      }
    }

    if (!nextTarget) {
      if (activeTarget) {
        const prevState = states.get(activeTarget)
        resetTarget(activeTarget, prevState)
        resetHeader(ctx, prevState)
        states.delete(activeTarget)
        activeTarget = null
      }
      return
    }

    if (activeTarget && activeTarget !== nextTarget) {
      const prevState = states.get(activeTarget)
      resetTarget(activeTarget, prevState)
      states.delete(activeTarget)
    }

    activeTarget = nextTarget
    let state = states.get(activeTarget)
    if (!state || state.headerEl !== ctx.el) {
      if (state) resetTarget(activeTarget, state)
      state = {
        headerEl: ctx.el,
        headerPrevTransition: ctx.el.style.transition || '',
        targetPrevTop: activeTarget.style.top || '',
        targetPrevTransition: activeTarget.style.transition || '',
        navMain: activeTarget.closest('.blocks-nav-main'),
        measureEl: getTargetMeasureEl(activeTarget),
        docTop: getTargetDocumentTop(activeTarget),
      }
      states.set(activeTarget, state)
      activeTarget.classList.add('pos_show')
      activeTarget.classList.add('sticky_anchor_active')
    }

    state.measureEl = getTargetMeasureEl(activeTarget, state)
    state.docTop = getTargetDocumentTop(activeTarget, state)
    nextTargetTop = state.docTop
    if (state.navMain) state.navMain.style.height = activeTarget.offsetHeight + 'px'

    // 无状态计算（同现有联动数学模型）：
    // targetViewportTop = docTop - scrollY
    // headerTop = clamp(targetViewportTop - headerH, [-headerH, 0])
    // navTop    = clamp(targetViewportTop, [0, headerH])
    // 满足：headerTop + headerH == navTop（头部底部永远贴合二级导航顶部，不重叠）
    const headerTotalH = ctx.totalH
    const targetViewportTop = nextTargetTop - scrolledY

    const headerTop = Math.max(-headerTotalH, Math.min(0, targetViewportTop - headerTotalH))
    ctx.el.style.transition = 'top 0ms linear'
    ctx.el.style.top = `${headerTop}px`

    const navTop = Math.max(0, Math.min(headerTotalH, targetViewportTop))
    activeTarget.style.transition = 'top 0ms linear'
    activeTarget.style.top = `${navTop}px`
  }

  const requestUpdate = () => {
    // 统一走 rAF，避免同一帧重复 update
    if (ticking) return
    ticking = true
    requestAnimationFrame(update)
  }

  let headerResizeObserver = null
  let headerObservedEl = null
  const syncHeaderResizeObserver = () => {
    // 头部高度运行时会变化（通知栏/IP定位 UI 延后渲染、收起动画等），需要触发一次重算避免遮挡
    const ctx = getHeaderContext()
    const el = ctx && ctx.el
    if (!el || el === headerObservedEl) return
    if (headerResizeObserver) headerResizeObserver.disconnect()
    headerResizeObserver = new ResizeObserver(() => {
      requestUpdate()
    })
    headerResizeObserver.observe(el)
    headerObservedEl = el
  }

  refreshTargets()
  targetsDirty = false
  syncHeaderResizeObserver()
  const observer = new MutationObserver((mutations) => {
    let shouldRefresh = false
    let shouldUpdate = false
    let shouldSyncHeader = false
    for (const m of mutations) {
      if (m.type === 'childList') {
        const nodes = [...m.addedNodes, ...m.removedNodes]
        for (const node of nodes) {
          if (node && node.nodeType === 1) {
            const el = node
            if (el.matches('.cal_scroll_target') || el.querySelector('.cal_scroll_target')) {
              shouldRefresh = true
            }
            if (el.matches('header-v5, jky-header, .shopify-section.jky-header, .site-header') || el.querySelector('header-v5, jky-header, .shopify-section.jky-header, .site-header')) {
              shouldUpdate = true
              shouldSyncHeader = true
            }
            if (el.matches('.locale-switcher, .announce-bar') || el.querySelector('.locale-switcher, .announce-bar')) {
              shouldUpdate = true
            }
          }
        }
      } else if (m.type === 'attributes') {
        const el = m.target
        if (!el || el.nodeType !== 1) continue
        if (m.attributeName === 'class') {
          if (el.classList.contains('cal_scroll_target') || (m.oldValue || '').includes('cal_scroll_target')) {
            shouldRefresh = true
          }
          if (el.classList.contains('locale-switcher') || (m.oldValue || '').includes('locale-switcher')) {
            shouldUpdate = true
          }
          if (el.classList.contains('announce-bar') || (m.oldValue || '').includes('announce-bar')) {
            shouldUpdate = true
          }
        }
      }
      if (shouldRefresh && shouldUpdate) break
    }
    if (shouldSyncHeader) syncHeaderResizeObserver()
    if (shouldRefresh) {
      targetsDirty = true
    }
    if (shouldRefresh || shouldUpdate) requestUpdate()
  })
  // 不监听 style：update 会写 style.top/transition，监听 style 会导致 observer 自触发带来性能问题
  observer.observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeOldValue: true, attributeFilter: ['class'] })

  window.addEventListener('scroll', () => {
    // 大幅滚动跃迁时（快速滚轮/触控 fling），补一次限频同步 update，减少错位窗口
    const y = window.scrollY || 0
    const bigJump = Math.abs(y - lastScrollY) > 120
    lastScrollY = y
    // 如果初始化时目标还不可见导致列表为空，用户开始滚动后再补一次刷新
    if (!calScrollTargets.length) targetsDirty = true
    if (bigJump && !ticking) {
      const now = performance.now()
      if (now - lastImmediateUpdateTs > 80) {
        lastImmediateUpdateTs = now
        update()
        return
      }
    }
    requestUpdate()
  }, { passive: true })
  window.addEventListener('resize', () => {
    // 视口变化会影响头部高度/目标布局，标记 dirty 后重算
    targetsDirty = true
    requestUpdate()
  })
  requestUpdate()
}
